import java.math.BigDecimal;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

public final class ScoreSummary {
    private static final int DEFAULT_MAX_MATCHES = 5;

    private final BigDecimal score;
    private final String constraintName;
    private final List<ConstraintMatch> matches;

    public ScoreSummary(
            BigDecimal score,
            String constraintName,
            List<ConstraintMatch> matches) {

        this.score = Objects.requireNonNull(score, "score must not be null");
        this.constraintName = Objects.requireNonNull(
                constraintName,
                "constraintName must not be null");
        this.matches = List.copyOf(
                Objects.requireNonNull(matches, "matches must not be null"));
    }

    /**
     * Summarizes the score and displays at most the default number of matches.
     */
    public String summarize() {
        return summarize(DEFAULT_MAX_MATCHES);
    }

    /**
     * Summarizes the score and displays at most {@code maximumMatches} matches.
     */
    public String summarize(int maximumMatches) {
        if (maximumMatches < 0) {
            throw new IllegalArgumentException(
                    "maximumMatches must not be negative");
        }

        List<ConstraintMatch> sortedMatches = matches.stream()
                .sorted(Comparator.comparing(ConstraintMatch::score))
                .toList();

        StringBuilder summary = new StringBuilder();
        summary.append("Explanation of score (")
                .append(formatScore(score))
                .append("):\n");
        summary.append("    Constraint: ")
                .append(constraintName)
                .append('\n');
        summary.append("    Total matches: ")
                .append(sortedMatches.size())
                .append('\n');

        if (sortedMatches.isEmpty()) {
            summary.append("    No constraint matches.\n");
            return summary.toString();
        }

        summary.append("    Constraint matches:\n");

        int displayedMatches = Math.min(maximumMatches, sortedMatches.size());
        for (int i = 0; i < displayedMatches; i++) {
            ConstraintMatch match = sortedMatches.get(i);
            summary.append("        ")
                    .append(i + 1)
                    .append(". score=")
                    .append(formatScore(match.score()))
                    .append(", justification=")
                    .append(match.justification())
                    .append('\n');
        }

        if (sortedMatches.size() > displayedMatches) {
            summary.append("        ... (")
                    .append(sortedMatches.size() - displayedMatches)
                    .append(" more matches)\n");
        }

        return summary.toString();
    }

    private static String formatScore(BigDecimal score) {
        return score.stripTrailingZeros().toPlainString();
    }

    public record ConstraintMatch(BigDecimal score, String justification) {
        public ConstraintMatch {
            Objects.requireNonNull(score, "match score must not be null");
            Objects.requireNonNull(
                    justification,
                    "match justification must not be null");
        }
    }
}

