import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;

public final class ConstraintScoreSummary {
    private static final int DEFAULT_MAX_MATCHES = 5;

    private final double score;
    private final String constraintName;
    private final List<ConstraintMatch> matches;

    public ConstraintScoreSummary(
            double score,
            String constraintName,
            List<ConstraintMatch> matches) {
        this.score = score;
        this.constraintName = Objects.requireNonNull(constraintName, "constraintName");
        this.matches = matches;
    }

    public String summarize() {
        if (matches == null) {
            throw new IllegalArgumentException(
                    "Constraint matches must be non-null. "
                            + "Use ScoreAnalysisFetchPolicy.FETCH_ALL to obtain the constraint match data.");
        }

        StringBuilder summary = new StringBuilder();
        summary.append("Overall score: ")
                .append(formatScore(score))
                .append('\n');

        summary.append("Constraint: ")
                .append(constraintName)
                .append('\n');

        summary.append("Number of matches: ")
                .append(matches.size())
                .append('\n');

        if (matches.isEmpty()) {
            summary.append("No matches: constraint ")
                    .append(constraintName)
                    .append(" has no matches (score: ")
                    .append(formatScore(score))
                    .append(").\n");
            return summary.toString();
        }

        summary.append("Matches:\n");

        List<ConstraintMatch> sortedMatches = new ArrayList<>(matches);
        sortedMatches.sort(Comparator.comparingDouble(ConstraintMatch::score));

        int displayedMatches = Math.min(DEFAULT_MAX_MATCHES, sortedMatches.size());
        for (int i = 0; i < displayedMatches; i++) {
            ConstraintMatch match = sortedMatches.get(i);
            summary.append("  - Score: ")
                    .append(formatScore(match.score()))
                    .append(", Justification: ")
                    .append(match.justification())
                    .append('\n');
        }

        if (sortedMatches.size() > DEFAULT_MAX_MATCHES) {
            summary.append("  ... and ")
                    .append(sortedMatches.size() - DEFAULT_MAX_MATCHES)
                    .append(" more match(es).\n");
        }

        return summary.toString();
    }

    private static String formatScore(double score) {
        return String.format("%.2f", score);
    }

    public record ConstraintMatch(double score, String justification) {
        public ConstraintMatch {
            Objects.requireNonNull(justification, "justification");
        }
    }
}

