public @NonNull ScoreAnalysis<Score_> diff(@NonNull ScoreAnalysis<Score_> other) {
    boolean hasMatchData = constraintMap.values().stream()
            .anyMatch(constraintAnalysis ->
                    constraintAnalysis.matches() != null
                            && !constraintAnalysis.matches().isEmpty());
    boolean otherHasMatchData = other.constraintMap.values().stream()
            .anyMatch(constraintAnalysis ->
                    constraintAnalysis.matches() != null
                            && !constraintAnalysis.matches().isEmpty());

    if (hasMatchData != otherHasMatchData) {
        throw new IllegalArgumentException(
                "Cannot diff score analyses when only one contains match data.");
    }

    var result = Stream.concat(
                    constraintMap.keySet().stream(),
                    other.constraintMap.keySet().stream())
            .distinct()
            .flatMap(constraintRef -> {
                var constraintAnalysis = getConstraintAnalysis(constraintRef);
                var otherConstraintAnalysis = other.getConstraintAnalysis(constraintRef);
                var constraintDiff = ConstraintAnalysis.diff(
                        constraintRef,
                        constraintAnalysis,
                        otherConstraintAnalysis);

                boolean hasWeightDifference = !constraintDiff.weight().isZero();
                boolean hasScoreDifference = !constraintDiff.score().isZero();
                boolean hasMatchDifference = constraintDiff.matches() != null
                        && !constraintDiff.matches().isEmpty();

                if (!hasWeightDifference && !hasScoreDifference && !hasMatchDifference) {
                    return Stream.empty();
                }

                return Stream.of(constraintDiff);
            })
            .collect(Collectors.toMap(
                    ConstraintAnalysis::constraintRef,
                    Function.identity(),
                    (existing, replacement) -> existing,
                    HashMap::new));

    return new ScoreAnalysis<>(
            score.subtract(other.score()),
            result,
            isSolutionInitialized);
}

